  LinearLayout backupBar=row(this);button(backupBar,"导出分组","watchWorkspaceBackupExport",()->{need(backupExportRequest!=null,"宿主尚未接文件导出");backupExportRequest.run();});button(backupBar,"选择备份","watchWorkspaceBackupImport",()->{need(backupImportRequest!=null,"宿主尚未接备份选择");backupImportRequest.run();});button(backupBar,"采用草稿","watchWorkspaceBackupAccept",this::acceptBackupImport);button(backupBar,"取消导入","watchWorkspaceBackupCancel",this::cancelBackupImport);
  status=label("",12);status.setMaxLines(3);status.setTag("watchWorkspaceStatus");addView(status);viewport=new ViewFlipper(c);viewport.setTag("watchWorkspaceViewport");addView(viewport,new LayoutParams(-1,0,1));
