 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView label(String s,int size){TextView v=new TextView(getContext());v.setText(s);v.setTextSize(size);v.setPadding(dp(4),dp(3),dp(4),dp(3));return v;}
 private EditText field(String hint,String tag){EditText v=new EditText(getContext());v.setSingleLine(true);v.setTextSize(14);v.setHint(hint);v.setTag(tag);return v;}
 private LinearLayout row(LinearLayout p){LinearLayout v=new LinearLayout(getContext());v.setOrientation(HORIZONTAL);p.addView(v,new LayoutParams(-1,dp(48)));return v;}
 private void button(LinearLayout row,String text,String tag,Action action){Button b=new Button(getContext());b.setText(text);b.setTextSize(12);b.setPadding(dp(2),0,dp(2),0);b.setTag(tag);row.addView(b,new LayoutParams(0,-1,1));b.setOnClickListener(v->attempt(action));}
 private void attempt(Action f){try{f.run();}catch(Exception e){status.setText((uncertain?"保存结果未确认；草稿保留，请明确重读。 ":"")+e.getMessage());}}
 private JSONObject currentGroup()throws Exception{if(!draft.has("groups"))return new JSONObject();JSONArray gs=draft.getJSONArray("groups");int at=groupIndex(gs,selected);return at<0?new JSONObject():gs.getJSONObject(at);}
 private String chosenMember()throws Exception{int at=members.getCheckedItemPosition();need(at>=0&&at<memberIds.size(),"请选择本组成员");return memberIds.get(at);}
 private void cleanEditor()throws Exception{need(importPreview.length()==0,"请先采用或取消导入预览，未覆盖已有编辑");JSONObject g=currentGroup();if(g.length()>0)need(name.getText().toString().equals(text(g,"name"))&&color.getText().toString().equals(text(g,"color")),"名称 / 识别色输入尚未确认到草稿，请先确认或取消草稿");}
 public void reload()throws Exception{need(reader!=null,"宿主尚未提供本机快照");JSONObject fresh=copy(validate(reader.read()));base=fresh;draft=copy(fresh);preview=new JSONObject();importPreview=new JSONObject();readText="";readOffset=0;evidence.setText("");uncertain=false;mode=0;render();status.setText("已读取本机分组；修改留在草稿，预览后提交。");}
 public void cancelChanges()throws Exception{reload();status.setText("草稿已取消；未调用保存。");}
 public void applyOperation(JSONObject op)throws Exception{need(!uncertain,"上次保存结果未确认；请明确重读后再编辑");cleanEditor();JSONObject next=apply(draft,op);transition(base,next);draft=next;preview=new JSONObject();mode=0;if(text(op,"op").equals("addGroup"))selected=text(op,"groupId");render();status.setText("变更仅在草稿；删除 / 移出只作用本组，主自选和其它组保留。");}
 private void metadata()throws Exception{need(importPreview.length()==0,"请先采用或取消导入预览");need(!uncertain,"保存结果未确认，请重读");JSONObject next=apply(draft,object("op","renameGroup","groupId",selected,"name",name.getText().toString().trim()));next=apply(next,object("op","setColor","groupId",selected,"color",color.getText().toString().trim()));transition(base,next);draft=next;preview=new JSONObject();mode=0;render();status.setText("名称 / 识别色已进入草稿；groupId未变化，未保存。");}
 public void previewChanges()throws Exception{need(!uncertain&&reader!=null,"保存结果未确认或快照回调未接，请重读");cleanEditor();preview=copy(prepare(base,draft,reader.read()));readText=describe(preview)+preview.toString(2);readOffset=0;paintReader();mode=1;viewport.setDisplayedChild(mode);status.setText("核对前后成员和顺序；确认提交后由宿主原子保存。");}
 public void commitChanges()throws Exception{need(!uncertain&&preview.length()>0&&reader!=null,"需先预览明确变更；未确认结果不得自动重试");cleanEditor();JSONObject now=prepare(base,draft,reader.read());need(equal(now,preview),"预览之后草稿已变，需重新预览");if(now.getBoolean("noChange")){preview=new JSONObject();mode=0;render();status.setText("没有变化；未调用保存。");return;}need(saver!=null,"宿主未接原子保存");uncertain=true;JSONObject saved=copy(receipt(base,draft,saver.save(copy(now))));base=saved;draft=copy(saved);preview=new JSONObject();readText="";readOffset=0;evidence.setText("");uncertain=false;mode=0;render();status.setText("分组已保存；行情与主自选未改。");}
 public JSONObject draftSnapshot()throws Exception{return copy(draft);}
 private void paintReader(){int start=Math.min(readOffset,readText.length()),end=Math.min(start+24000,readText.length());if(start>0&&start<readText.length()&&Character.isLowSurrogate(readText.charAt(start)))start--;if(end<readText.length()&&end>0&&Character.isHighSurrogate(readText.charAt(end-1)))end--;evidence.setText("完整变更预览 "+start+"–"+end+" / "+readText.length()+"\n"+readText.substring(start,end));}
 private void adapter(ListView view,List<String>labels,boolean groupRows){view.setAdapter(new ArrayAdapter<String>(getContext(),android.R.layout.simple_list_item_single_choice,labels){public View getView(int at,View old,ViewGroup parent){TextView t=(TextView)super.getView(at,old,parent);t.setTextSize(13);t.setContentDescription(labels.get(at)+" · "+(groupRows?groupIds.get(at):memberIds.get(at)));t.setTextColor(dark?Color.rgb(220,229,240):Color.rgb(36,52,73));if(groupRows)try{String c=draft.getJSONArray("groups").getJSONObject(at).getString("color");if(!c.isEmpty())t.setTextColor(Color.parseColor(c));}catch(Exception ignored){}return t;}});}
 private void rosterChoices()throws Exception{String chosen=roster.getSelectedItemPosition()>=0&&roster.getSelectedItemPosition()<rosterIds.size()?rosterIds.get(roster.getSelectedItemPosition()):"";rosterIds.clear();rosterIds.add("");List<String>labels=new ArrayList<>();labels.add("请选择完整证券身份");String needle=search.getText().toString().trim().toLowerCase(Locale.ROOT);JSONArray all=draft.optJSONArray("instruments");if(all!=null)for(int i=0;i<all.length();i++){JSONObject r=all.getJSONObject(i);String label=text(r,"name")+" · "+text(r,"id");if(needle.isEmpty()||label.toLowerCase(Locale.ROOT).contains(needle)){labels.add(label);rosterIds.add(text(r,"id"));}}roster.setAdapter(new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_dropdown_item,labels){private View paint(View v){((TextView)v).setTextColor(dark?Color.rgb(220,229,240):Color.rgb(36,52,73));v.setBackgroundColor(dark?Color.rgb(23,34,50):Color.rgb(244,247,251));return v;}public View getView(int n,View old,ViewGroup p){return paint(super.getView(n,old,p));}public View getDropDownView(int n,View old,ViewGroup p){return paint(super.getDropDownView(n,old,p));}});roster.setSelection(Math.max(0,rosterIds.indexOf(chosen)));}
 private void render()throws Exception{String member=members.getCheckedItemPosition()>=0&&members.getCheckedItemPosition()<memberIds.size()?memberIds.get(members.getCheckedItemPosition()):"";groupIds.clear();List<String>labels=new ArrayList<>();JSONArray gs=draft.getJSONArray("groups");if(groupIndex(gs,selected)<0)selected=gs.length()==0?"":text(gs.getJSONObject(0),"groupId");for(int i=0;i<gs.length();i++){JSONObject g=gs.getJSONObject(i);groupIds.add(text(g,"groupId"));labels.add(text(g,"name")+" · "+g.getJSONArray("memberIds").length()+"只"+(g.getBoolean("readOnly")?" · 只读":" · 本地"));}adapter(groups,labels,true);if(groupIds.indexOf(selected)>=0)groups.setItemChecked(groupIds.indexOf(selected),true);JSONObject g=currentGroup();name.setText(g.optString("name",""));color.setText(g.optString("color",""));name.setEnabled(g.length()>0&&!g.optBoolean("readOnly"));color.setEnabled(name.isEnabled());memberIds.clear();JSONArray ms=g.optJSONArray("memberIds");if(ms!=null)for(int i=0;i<ms.length();i++)memberIds.add(ms.getString(i));List<String>memberLabels=new ArrayList<>();JSONArray all=draft.getJSONArray("instruments");for(String id:memberIds){String label=id;for(int i=0;i<all.length();i++)if(id.equals(all.getJSONObject(i).optString("id"))){label=all.getJSONObject(i).optString("name")+"  "+id;break;}memberLabels.add(label);}adapter(members,memberLabels,false);if(memberIds.contains(member))members.setItemChecked(memberIds.indexOf(member),true);rosterChoices();viewport.setDisplayedChild(mode);style(this);}
 public JSONObject saveViewState()throws Exception{if(base.length()==0)return new JSONObject();return object("schema","watchlist-workspace-view/v1","base",management(base),"draftGroups",draft.get("groups"),"selectedGroupId",selected,"memberId",members.getCheckedItemPosition()>=0&&members.getCheckedItemPosition()<memberIds.size()?memberIds.get(members.getCheckedItemPosition()):"","nameInput",name.getText().toString(),"colorInput",color.getText().toString(),"newNameInput",newName.getText().toString(),"search",search.getText().toString(),"uncertain",uncertain);}
 public Bundle saveState()throws Exception{String text=saveViewState().toString();need(text.getBytes(StandardCharsets.UTF_8).length<=128*1024&&text.length()<=64000,"分组草稿较大，请由宿主保存完整saveViewState到其独立状态位置；未截断草稿");Bundle b=new Bundle();b.putString("watchlistWorkspace",text);return b;}
 public void restoreState(Bundle b)throws Exception{if(b==null)return;String raw=b.getString("watchlistWorkspace");if(raw!=null)restoreViewState(new JSONObject(raw));}
 public void restoreViewState(JSONObject state)throws Exception{if(state.length()==0)return;need(text(state,"schema").equals("watchlist-workspace-view/v1")&&state.opt("base") instanceof JSONObject&&state.opt("draftGroups") instanceof JSONArray&&state.opt("uncertain") instanceof Boolean,"分组草稿状态损坏，未采用");JSONObject b=copy(validate(state.getJSONObject("base"))),d=copy(b);d.put("groups",state.getJSONArray("draftGroups"));transition(b,d);if(reader!=null){JSONObject fresh=copy(validate(reader.read()));if(equal(fresh.get("revision"),b.get("revision"))&&fingerprint(fresh).equals(fingerprint(b))){b=fresh;d=copy(b);d.put("groups",state.getJSONArray("draftGroups"));}}base=b;draft=copy(d);importPreview=new JSONObject();selected=text(state,"selectedGroupId");uncertain=state.getBoolean("uncertain");preview=new JSONObject();mode=0;render();name.setText(text(state,"nameInput"));color.setText(text(state,"colorInput"));newName.setText(text(state,"newNameInput"));search.setText(text(state,"search"));String member=text(state,"memberId");if(memberIds.contains(member))members.setItemChecked(memberIds.indexOf(member),true);status.setText("未保存草稿已恢复；需重新预览，版本变化将拒绝提交。");}
 public boolean back(){if(importPreview.length()>0){cancelBackupImport();return true;}if(mode!=0){mode=0;viewport.setDisplayedChild(0);return true;}try{JSONObject g=currentGroup();boolean input=g.length()>0&&(!name.getText().toString().equals(text(g,"name"))||!color.getText().toString().equals(text(g,"color")));if(uncertain||input||!equal(base.opt("groups"),draft.opt("groups"))){status.setText("存在未保存草稿或未确认保存结果；请明确取消 / 重读或提交后离开。");return true;}}catch(Exception e){status.setText(e.getMessage());return true;}return false;}
 public void setDarkTheme(boolean value){dark=value;setBackgroundColor(dark?Color.rgb(17,26,38):Color.WHITE);style(this);groups.invalidateViews();members.invalidateViews();if(roster.getAdapter() instanceof ArrayAdapter)((ArrayAdapter<?>)roster.getAdapter()).notifyDataSetChanged();}
 private void style(View v){int fg=dark?Color.rgb(220,229,240):Color.rgb(36,52,73);if(v instanceof ListView||v instanceof Spinner)return;if(v instanceof TextView){((TextView)v).setTextColor(fg);if(v instanceof EditText)((EditText)v).setHintTextColor(dark?Color.rgb(149,164,180):Color.rgb(95,111,128));}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)style(((ViewGroup)v).getChildAt(i));}
 protected void onMeasure(int width,int height){int h=View.MeasureSpec.getSize(height);disclosure.setVisibility(h<dp(360)?GONE:VISIBLE);status.setMaxLines(h<dp(360)?1:3);super.onMeasure(width,height);}

 public void setBackupActions(BackupRequest e,BackupRequest i){backupExportRequest=e;backupImportRequest=i;}
 private void cleanImportTarget()throws Exception{need(!uncertain&&base.length()>0&&equal(base.opt("groups"),draft.opt("groups")),"已有未保存草稿或保存结果未确认；导入未替换，请先明确处理");JSONObject g=currentGroup();need((g.length()==0||(name.getText().toString().equals(text(g,"name"))&&color.getText().toString().equals(text(g,"color"))))&&newName.getText().length()==0,"已有未确认名称/颜色/新组输入；导入未覆盖");}
 public byte[] exportBackupBytes()throws Exception{need(!uncertain&&reader!=null,"保存结果未确认或宿主未接快照；未导出");return WatchlistBackupModel.encodeBackup(WatchlistBackupModel.exportBackup(reader.read()));}
 public void previewBackupImport(byte[] bytes)throws Exception{need(importPreview.length()==0,"已有导入预览，请先采用或取消");cleanImportTarget();need(reader!=null,"宿主未接当前快照");JSONObject candidate=WatchlistBackupModel.previewImport(WatchlistBackupModel.decodeBackup(bytes),base,reader.read());importPreview=copy(candidate);preview=new JSONObject();readText="分组备份差异预览 · 8 MiB上限\n采用后仅进入草稿；仍需预览变更并确认提交。\n"+describe(candidate.getJSONObject("change"))+candidate.toString(2);readOffset=0;paintReader();mode=1;viewport.setDisplayedChild(mode);status.setText("备份已校验；只读来源组与当前一致。尚未改变草稿或保存。");}
 public void acceptBackupImport()throws Exception{need(importPreview.length()>0&&reader!=null,"需先选择备份并预览");cleanImportTarget();JSONObject next=WatchlistBackupModel.importDraft(base,importPreview,reader.read());draft=copy(next);importPreview=new JSONObject();preview=new JSONObject();readText="";readOffset=0;evidence.setText("");mode=0;render();status.setText("完整分组配置已进入草稿；请预览变更后确认提交。主自选行情未改。");}
 public void cancelBackupImport(){if(importPreview.length()==0)return;importPreview=new JSONObject();readText="";readOffset=0;evidence.setText("");mode=0;viewport.setDisplayedChild(0);status.setText("导入预览已取消；原草稿/输入保留，未调用保存。");}

